// --- samp_mdb.FDb.ind_user.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
samp_mdb::User& samp_mdb::ind_user_GetOrCreate(const algo::strptr& key) {
    samp_mdb::User* ret = ind_user_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &user_Alloc();
        (*ret).user = key;
        bool good = user_XrefMaybe(*ret);
        if (!good) {
            user_Delete(*ret); // delete offending row, any existin xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "samp_mdb.create_error  table:ind_user  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- samp_mdb.FDb.ind_user.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool samp_mdb::ind_user_InsertMaybe(samp_mdb::User& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_user_next == (samp_mdb::User*)-1)) {// check if in hash already
        row.ind_user_hashval = algo::Smallstr50_Hash(0, row.user);
        ind_user_Reserve(1);
        u32 index = row.ind_user_hashval & (_db.ind_user_buckets_n - 1);
        samp_mdb::User* *prev = &_db.ind_user_buckets_elems[index];
        do {
            samp_mdb::User* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).user == row.user) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_user_next;
        } while (true);
        if (retval) {
            row.ind_user_next = *prev;
            _db.ind_user_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- samp_mdb.FDb.ind_user.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void samp_mdb::ind_user_Remove(samp_mdb::User& row) {
    if (LIKELY(row.ind_user_next != (samp_mdb::User*)-1)) {// check if in hash already
        u32 index = row.ind_user_hashval & (_db.ind_user_buckets_n - 1);
        samp_mdb::User* *prev = &_db.ind_user_buckets_elems[index]; // addr of pointer to current element
        while (samp_mdb::User *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_user_next; // unlink (singly linked list)
                _db.ind_user_n--;
                row.ind_user_next = (samp_mdb::User*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_user_next;
        }
    }
}

// --- samp_mdb.FDb.ind_user.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void samp_mdb::ind_user_Reserve(int n) {
    ind_user_AbsReserve(_db.ind_user_n + n);
}

// --- samp_mdb.FDb.ind_user.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void samp_mdb::ind_user_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_user_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(samp_mdb::User*);
        u32 new_size = new_nbuckets * sizeof(samp_mdb::User*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        samp_mdb::User* *new_buckets = (samp_mdb::User**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("samp_mdb.out_of_memory  field:samp_mdb.FDb.ind_user");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_user_buckets_n; i++) {
            samp_mdb::User* elem = _db.ind_user_buckets_elems[i];
            while (elem) {
                samp_mdb::User &row        = *elem;
                samp_mdb::User* next       = row.ind_user_next;
                u32 index          = row.ind_user_hashval & (new_nbuckets-1);
                row.ind_user_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_user_buckets_elems, old_size);
        _db.ind_user_buckets_elems = new_buckets;
        _db.ind_user_buckets_n = new_nbuckets;
    }
}

// --- samp_mdb.FDb.zd_user.Insert
// Insert row into linked list. If row is already in linked list, do nothing.
void samp_mdb::zd_user_Insert(samp_mdb::User& row) {
    if (!zd_user_InLlistQ(row)) {
        samp_mdb::User* old_tail = _db.zd_user_tail;
        row.zd_user_next = NULL;
        row.zd_user_prev = old_tail;
        _db.zd_user_tail = &row;
        samp_mdb::User **new_row_a = &old_tail->zd_user_next;
        samp_mdb::User **new_row_b = &_db.zd_user_head;
        samp_mdb::User **new_row = old_tail ? new_row_a : new_row_b;
        *new_row = &row;
        _db.zd_user_n++;
    }
}

// --- samp_mdb.FDb.zd_user.Remove
// Remove element from index. If element is not in index, do nothing.
void samp_mdb::zd_user_Remove(samp_mdb::User& row) {
    if (zd_user_InLlistQ(row)) {
        samp_mdb::User* old_head       = _db.zd_user_head;
        (void)old_head; // in case it's not used
        samp_mdb::User* prev = row.zd_user_prev;
        samp_mdb::User* next = row.zd_user_next;
        // if element is first, adjust list head; otherwise, adjust previous element's next
        samp_mdb::User **new_next_a = &prev->zd_user_next;
        samp_mdb::User **new_next_b = &_db.zd_user_head;
        samp_mdb::User **new_next = prev ? new_next_a : new_next_b;
        *new_next = next;
        // if element is last, adjust list tail; otherwise, adjust next element's prev
        samp_mdb::User **new_prev_a = &next->zd_user_prev;
        samp_mdb::User **new_prev_b = &_db.zd_user_tail;
        samp_mdb::User **new_prev = next ? new_prev_a : new_prev_b;
        *new_prev = prev;
        _db.zd_user_n--;
        row.zd_user_next=(samp_mdb::User*)-1; // not-in-list
    }
}

// --- samp_mdb.FDb.zd_user.RemoveAll
// Empty the index. (The rows are not deleted)
void samp_mdb::zd_user_RemoveAll() {
    samp_mdb::User* row = _db.zd_user_head;
    _db.zd_user_head = NULL;
    _db.zd_user_tail = NULL;
    _db.zd_user_n = 0;
    while (row) {
        samp_mdb::User* row_next = row->zd_user_next;
        row->zd_user_next  = (samp_mdb::User*)-1;
        row->zd_user_prev  = NULL;
        row = row_next;
    }
}

// --- samp_mdb.FDb.zd_user.RemoveFirst
// If linked list is empty, return NULL. Otherwise unlink and return pointer to first element.
samp_mdb::User* samp_mdb::zd_user_RemoveFirst() {
    samp_mdb::User *row = NULL;
    row = _db.zd_user_head;
    if (row) {
        samp_mdb::User *next = row->zd_user_next;
        _db.zd_user_head = next;
        samp_mdb::User **new_end_a = &next->zd_user_prev;
        samp_mdb::User **new_end_b = &_db.zd_user_tail;
        samp_mdb::User **new_end = next ? new_end_a : new_end_b;
        *new_end = NULL;
        _db.zd_user_n--;
        row->zd_user_next = (samp_mdb::User*)-1; // mark as not-in-list
    }
    return row;
}

