// --- samp_mdb.FDb.project.AllocMem
// Allocate space for one element
// If no memory available, return NULL.
void* samp_mdb::project_AllocMem() {
    samp_mdb::Project *row = _db.project_free;
    if (UNLIKELY(!row)) {
        project_Reserve(1);
        row = _db.project_free;
    }
    if (row) {
        _db.project_free = row->project_next;
    }
    return row;
}

// --- samp_mdb.FDb.project.FreeMem
// Remove mem from all global and cross indices, then deallocate mem
void samp_mdb::project_FreeMem(samp_mdb::Project &row) {
    if (UNLIKELY(row.project_next != (samp_mdb::Project*)-1)) {
        FatalErrorExit("samp_mdb.tpool_double_delete  pool:samp_mdb.FDb.project  comment:'double deletion caught'");
    }
    row.project_next = _db.project_free; // insert into free list
    _db.project_free  = &row;
}

// --- samp_mdb.FDb.project.Reserve
// Preallocate memory for N more elements
// Return number of elements actually reserved.
u64 samp_mdb::project_Reserve(u64 n_elems) {
    u64 ret = 0;
    while (ret < n_elems) {
        u64 size = _db.project_blocksize; // underlying allocator is probably Lpool
        u64 reserved = project_ReserveMem(size);
        ret += reserved;
        if (reserved == 0) {
            break;
        }
    }
    return ret;
}

// --- samp_mdb.FDb.project.ReserveMem
// Allocate block of given size, break up into small elements and append to free list.
// Return number of elements reserved.
u64 samp_mdb::project_ReserveMem(u64 size) {
    u64 ret = 0;
    if (size >= sizeof(samp_mdb::Project)) {
        samp_mdb::Project *mem = (samp_mdb::Project*)algo_lib::malloc_AllocMem(size);
        ret = mem ? size / sizeof(samp_mdb::Project) : 0;
        // add newly allocated elements to the free list;
        for (u64 i=0; i < ret; i++) {
            mem[i].project_next = _db.project_free;
            _db.project_free = mem+i;
        }
    }
    return ret;
}

