bool samp_mdb::project_XrefMaybe(samp_mdb::Project &row) {
    bool retval = true;
    (void)row;
    // insert project into index ind_project
    if (true) { // user-defined insert condition
        bool success = ind_project_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "samp_mdb.duplicate_key  xref:samp_mdb.FDb.ind_project"; // check for duplicate key
            return false;
        }
    }
    // insert project into index zd_project
    if (true) { // user-defined insert condition
        zd_project_Insert(row);
    }
    return retval;
}

