samp_mdb::Project* samp_mdb::ind_project_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr50_Hash(0, key) & (_db.ind_project_buckets_n - 1);
    samp_mdb::Project *ret = _db.ind_project_buckets_elems[index];
    for (; ret && !((*ret).project == key); ret = ret->ind_project_next) {
    }
    return ret;
}

// --- samp_mdb.FDb.ind_project.FindX
// Look up row by key and return reference. Throw exception if not found
samp_mdb::Project& samp_mdb::ind_project_FindX(const algo::strptr& key) {
    samp_mdb::Project* ret = ind_project_Find(key);
    vrfy(ret, tempstr() << "samp_mdb.key_error  table:ind_project  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- samp_mdb.FDb.ind_project.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
samp_mdb::Project& samp_mdb::ind_project_GetOrCreate(const algo::strptr& key) {
    samp_mdb::Project* ret = ind_project_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &project_Alloc();
        (*ret).project = key;
        bool good = project_XrefMaybe(*ret);
        if (!good) {
            project_Delete(*ret); // delete offending row, any existin xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "samp_mdb.create_error  table:ind_project  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- samp_mdb.FDb.ind_project.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool samp_mdb::ind_project_InsertMaybe(samp_mdb::Project& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_project_next == (samp_mdb::Project*)-1)) {// check if in hash already
        row.ind_project_hashval = algo::Smallstr50_Hash(0, row.project);
        ind_project_Reserve(1);
        u32 index = row.ind_project_hashval & (_db.ind_project_buckets_n - 1);
        samp_mdb::Project* *prev = &_db.ind_project_buckets_elems[index];
        do {
            samp_mdb::Project* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).project == row.project) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_project_next;
        } while (true);
        if (retval) {
            row.ind_project_next = *prev;
            _db.ind_project_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- samp_mdb.FDb.ind_project.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void samp_mdb::ind_project_Remove(samp_mdb::Project& row) {
    if (LIKELY(row.ind_project_next != (samp_mdb::Project*)-1)) {// check if in hash already
        u32 index = row.ind_project_hashval & (_db.ind_project_buckets_n - 1);
        samp_mdb::Project* *prev = &_db.ind_project_buckets_elems[index]; // addr of pointer to current element
        while (samp_mdb::Project *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_project_next; // unlink (singly linked list)
                _db.ind_project_n--;
                row.ind_project_next = (samp_mdb::Project*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_project_next;
        }
    }
}

// --- samp_mdb.FDb.ind_project.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void samp_mdb::ind_project_Reserve(int n) {
    ind_project_AbsReserve(_db.ind_project_n + n);
}

// --- samp_mdb.FDb.ind_project.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void samp_mdb::ind_project_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_project_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(samp_mdb::Project*);
        u32 new_size = new_nbuckets * sizeof(samp_mdb::Project*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        samp_mdb::Project* *new_buckets = (samp_mdb::Project**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("samp_mdb.out_of_memory  field:samp_mdb.FDb.ind_project");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_project_buckets_n; i++) {
            samp_mdb::Project* elem = _db.ind_project_buckets_elems[i];
            while (elem) {
                samp_mdb::Project &row        = *elem;
                samp_mdb::Project* next       = row.ind_project_next;
                u32 index          = row.ind_project_hashval & (new_nbuckets-1);
                row.ind_project_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_project_buckets_elems, old_size);
        _db.ind_project_buckets_elems = new_buckets;
        _db.ind_project_buckets_n = new_nbuckets;
    }
}

// --- samp_mdb.FDb.zd_project.Insert
// Insert row into linked list. If row is already in linked list, do nothing.
void samp_mdb::zd_project_Insert(samp_mdb::Project& row) {
    if (!zd_project_InLlistQ(row)) {
        samp_mdb::Project* old_tail = _db.zd_project_tail;
        row.zd_project_next = NULL;
        row.zd_project_prev = old_tail;
        _db.zd_project_tail = &row;
        samp_mdb::Project **new_row_a = &old_tail->zd_project_next;
        samp_mdb::Project **new_row_b = &_db.zd_project_head;
        samp_mdb::Project **new_row = old_tail ? new_row_a : new_row_b;
        *new_row = &row;
        _db.zd_project_n++;
    }
}

// --- samp_mdb.FDb.zd_project.Remove
// Remove element from index. If element is not in index, do nothing.
void samp_mdb::zd_project_Remove(samp_mdb::Project& row) {
    if (zd_project_InLlistQ(row)) {
        samp_mdb::Project* old_head       = _db.zd_project_head;
        (void)old_head; // in case it's not used
        samp_mdb::Project* prev = row.zd_project_prev;
        samp_mdb::Project* next = row.zd_project_next;
        // if element is first, adjust list head; otherwise, adjust previous element's next
        samp_mdb::Project **new_next_a = &prev->zd_project_next;
        samp_mdb::Project **new_next_b = &_db.zd_project_head;
        samp_mdb::Project **new_next = prev ? new_next_a : new_next_b;
        *new_next = next;
        // if element is last, adjust list tail; otherwise, adjust next element's prev
        samp_mdb::Project **new_prev_a = &next->zd_project_prev;
        samp_mdb::Project **new_prev_b = &_db.zd_project_tail;
        samp_mdb::Project **new_prev = next ? new_prev_a : new_prev_b;
        *new_prev = prev;
        _db.zd_project_n--;
        row.zd_project_next=(samp_mdb::Project*)-1; // not-in-list
    }
}

// --- samp_mdb.FDb.zd_project.RemoveAll
// Empty the index. (The rows are not deleted)
void samp_mdb::zd_project_RemoveAll() {
    samp_mdb::Project* row = _db.zd_project_head;
    _db.zd_project_head = NULL;
    _db.zd_project_tail = NULL;
    _db.zd_project_n = 0;
    while (row) {
        samp_mdb::Project* row_next = row->zd_project_next;
        row->zd_project_next  = (samp_mdb::Project*)-1;
        row->zd_project_prev  = NULL;
        row = row_next;
    }
}

// --- samp_mdb.FDb.zd_project.RemoveFirst
// If linked list is empty, return NULL. Otherwise unlink and return pointer to first element.
samp_mdb::Project* samp_mdb::zd_project_RemoveFirst() {
    samp_mdb::Project *row = NULL;
    row = _db.zd_project_head;
    if (row) {
        samp_mdb::Project *next = row->zd_project_next;
        _db.zd_project_head = next;
        samp_mdb::Project **new_end_a = &next->zd_project_prev;
        samp_mdb::Project **new_end_b = &_db.zd_project_tail;
        samp_mdb::Project **new_end = next ? new_end_a : new_end_b;
        *new_end = NULL;
        _db.zd_project_n--;
        row->zd_project_next = (samp_mdb::Project*)-1; // mark as not-in-list
    }
    return row;
}

