// --- samp_mdb.FDb.task.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool samp_mdb::task_XrefMaybe(samp_mdb::Task &row) {
    bool retval = true;
    (void)row;
    // insert task into index ind_task
    if (true) { // user-defined insert condition
        bool success = ind_task_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "samp_mdb.duplicate_key  xref:samp_mdb.FDb.ind_task"; // check for duplicate key
            return false;
        }
    }
    // insert task into index zd_task
    if (true) { // user-defined insert condition
        zd_task_Insert(row);
    }
    samp_mdb::Project* p_p_project = samp_mdb::ind_project_Find(row.p_project);
    if (UNLIKELY(!p_p_project)) {
        algo_lib::ResetErrtext() << "samp_mdb.bad_xref  index:samp_mdb.FDb.ind_project" << Keyval("key", row.p_project);
        return false;
    }
    // insert task into index zd_task
    if (true) { // user-defined insert condition
        zd_task_Insert(*p_p_project, row);
    }
    samp_mdb::User* p_p_user = samp_mdb::ind_user_Find(row.p_user);
    if (UNLIKELY(!p_p_user)) {
        algo_lib::ResetErrtext() << "samp_mdb.bad_xref  index:samp_mdb.FDb.ind_user" << Keyval("key", row.p_user);
        return false;
    }
    // insert task into index zd_task
    if (true) { // user-defined insert condition
        zd_task_Insert(*p_p_user, row);
    }
    // insert task into index bh_task
    if (true) { // user-defined insert condition
        bh_task_Insert(row);
    }
    // insert task into index zd_task_priority
    if (true) { // user-defined insert condition
        zd_task_priority_Insert(row);
    }
    return retval;
}

