// --- samp_mdb.FDb.bh_task_curs.Add
static void samp_mdb::_db_bh_task_curs_Add(_db_bh_task_curs &curs, samp_mdb::Task& row) {
    u32 n = curs.temp_n;
    int i = n;
    curs.temp_n = n+1;
    samp_mdb::Task* *elems = curs.temp_elems;
    while (i>0) {
        int j = (i-1)/2;
        samp_mdb::Task* p = elems[j];
        if (!bh_task_ElemLt(row,*p)) {
            break;
        }
        elems[i]=p;
        i=j;
    }
    elems[i]=&row;
}

// --- samp_mdb.FDb.bh_task_curs.Reserve
void samp_mdb::_db_bh_task_curs_Reserve(_db_bh_task_curs &curs, int n) {
    if (n > curs.temp_max) {
        size_t old_size   = sizeof(void*) * curs.temp_max;
        size_t new_size   = sizeof(void*) * bh_task_N();
        curs.temp_elems   = (samp_mdb::Task**)algo_lib::malloc_ReallocMem(curs.temp_elems, old_size, new_size);
        if (!curs.temp_elems) {
            algo::FatalErrorExit("samp_mdb.cursor_out_of_memory  func:samp_mdb.FDb.bh_task_curs.Reserve");
        }
        curs.temp_max       = bh_task_N();
    }
}

// --- samp_mdb.FDb.bh_task_curs.Reset
// Reset cursor. If HEAP is non-empty, add its top element to CURS.
void samp_mdb::_db_bh_task_curs_Reset(_db_bh_task_curs &curs, samp_mdb::FDb &parent) {
    curs.parent       = &parent;
    _db_bh_task_curs_Reserve(curs, bh_task_N());
    curs.temp_n = 0;
    if (parent.bh_task_n > 0) {
        samp_mdb::Task &first = *parent.bh_task_elems[0];
        curs.temp_elems[0] = &first; // insert first element in heap
        curs.temp_n = 1;
    }
}

// --- samp_mdb.FDb.bh_task_curs.Next
// Advance cursor.
void samp_mdb::_db_bh_task_curs_Next(_db_bh_task_curs &curs) {
    samp_mdb::Task* *elems = curs.temp_elems;
    int n = curs.temp_n;
    if (n > 0) {
        // remove top element from heap
        samp_mdb::Task* dead = elems[0];
        int i       = 0;
        samp_mdb::Task* last = curs.temp_elems[n-1];
        // downheap last elem
        do {
            samp_mdb::Task* choose = last;
            int l         = i*2+1;
            if (l<n) {
                samp_mdb::Task* el = elems[l];
                int r     = l+1;
                r        -= r==n;
                samp_mdb::Task* er = elems[r];
                if (bh_task_ElemLt(*er,*el)) {
                    el  = er;
                    l   = r;
                }
                bool b = bh_task_ElemLt(*el,*last);
                if (b) choose = el;
                if (!b) l = n;
            }
            elems[i] = choose;
            i = l;
        } while (i < n);
        curs.temp_n = n-1;
        int index = dead->bh_task_idx;
        i = (index*2+1);
        if (i < bh_task_N()) {
            samp_mdb::Task &elem = *curs.parent->bh_task_elems[i];
            _db_bh_task_curs_Add(curs, elem);
        }
        if (i+1 < bh_task_N()) {
            samp_mdb::Task &elem = *curs.parent->bh_task_elems[i + 1];
            _db_bh_task_curs_Add(curs, elem);
        }
    }
}

// --- samp_mdb.FDb..Init
// Set all fields to initial values.
void samp_mdb::FDb_Init() {
    // user: initialize Tpool
    _db.user_free      = NULL;
    _db.user_blocksize = algo::BumpToPow2(64 * sizeof(samp_mdb::User)); // allocate 64-127 elements at a time
    // initialize hash table for samp_mdb::User;
    _db.ind_user_n             	= 0; // (samp_mdb.FDb.ind_user)
    _db.ind_user_buckets_n     	= 4; // (samp_mdb.FDb.ind_user)
    _db.ind_user_buckets_elems 	= (samp_mdb::User**)algo_lib::malloc_AllocMem(sizeof(samp_mdb::User*)*_db.ind_user_buckets_n); // initial buckets (samp_mdb.FDb.ind_user)
    if (!_db.ind_user_buckets_elems) {
        FatalErrorExit("out of memory"); // (samp_mdb.FDb.ind_user)
    }
    memset(_db.ind_user_buckets_elems, 0, sizeof(samp_mdb::User*)*_db.ind_user_buckets_n); // (samp_mdb.FDb.ind_user)
    _db.zd_user_head = NULL; // (samp_mdb.FDb.zd_user)
    _db.zd_user_n = 0; // (samp_mdb.FDb.zd_user)
    _db.zd_user_tail = NULL; // (samp_mdb.FDb.zd_user)
    // project: initialize Tpool
    _db.project_free      = NULL;
    _db.project_blocksize = algo::BumpToPow2(64 * sizeof(samp_mdb::Project)); // allocate 64-127 elements at a time
    // initialize hash table for samp_mdb::Project;
    _db.ind_project_n             	= 0; // (samp_mdb.FDb.ind_project)
    _db.ind_project_buckets_n     	= 4; // (samp_mdb.FDb.ind_project)
    _db.ind_project_buckets_elems 	= (samp_mdb::Project**)algo_lib::malloc_AllocMem(sizeof(samp_mdb::Project*)*_db.ind_project_buckets_n); // initial buckets (samp_mdb.FDb.ind_project)
    if (!_db.ind_project_buckets_elems) {
        FatalErrorExit("out of memory"); // (samp_mdb.FDb.ind_project)
    }
    memset(_db.ind_project_buckets_elems, 0, sizeof(samp_mdb::Project*)*_db.ind_project_buckets_n); // (samp_mdb.FDb.ind_project)
    _db.zd_project_head = NULL; // (samp_mdb.FDb.zd_project)
    _db.zd_project_n = 0; // (samp_mdb.FDb.zd_project)
    _db.zd_project_tail = NULL; // (samp_mdb.FDb.zd_project)
    // task: initialize Tpool
    _db.task_free      = NULL;
    _db.task_blocksize = algo::BumpToPow2(64 * sizeof(samp_mdb::Task)); // allocate 64-127 elements at a time
    // initialize hash table for samp_mdb::Task;
    _db.ind_task_n             	= 0; // (samp_mdb.FDb.ind_task)
    _db.ind_task_buckets_n     	= 4; // (samp_mdb.FDb.ind_task)
    _db.ind_task_buckets_elems 	= (samp_mdb::Task**)algo_lib::malloc_AllocMem(sizeof(samp_mdb::Task*)*_db.ind_task_buckets_n); // initial buckets (samp_mdb.FDb.ind_task)
    if (!_db.ind_task_buckets_elems) {
        FatalErrorExit("out of memory"); // (samp_mdb.FDb.ind_task)
    }
    memset(_db.ind_task_buckets_elems, 0, sizeof(samp_mdb::Task*)*_db.ind_task_buckets_n); // (samp_mdb.FDb.ind_task)
    _db.zd_task_head = NULL; // (samp_mdb.FDb.zd_task)
    _db.zd_task_n = 0; // (samp_mdb.FDb.zd_task)
    _db.zd_task_tail = NULL; // (samp_mdb.FDb.zd_task)
    // comment: initialize Tpool
    _db.comment_free      = NULL;
    _db.comment_blocksize = algo::BumpToPow2(64 * sizeof(samp_mdb::Comment)); // allocate 64-127 elements at a time
    // initialize hash table for samp_mdb::Comment;
    _db.ind_comment_n             	= 0; // (samp_mdb.FDb.ind_comment)
    _db.ind_comment_buckets_n     	= 4; // (samp_mdb.FDb.ind_comment)
    _db.ind_comment_buckets_elems 	= (samp_mdb::Comment**)algo_lib::malloc_AllocMem(sizeof(samp_mdb::Comment*)*_db.ind_comment_buckets_n); // initial buckets (samp_mdb.FDb.ind_comment)
    if (!_db.ind_comment_buckets_elems) {
        FatalErrorExit("out of memory"); // (samp_mdb.FDb.ind_comment)
    }
    memset(_db.ind_comment_buckets_elems, 0, sizeof(samp_mdb::Comment*)*_db.ind_comment_buckets_n); // (samp_mdb.FDb.ind_comment)
    _db.zd_comment_head = NULL; // (samp_mdb.FDb.zd_comment)
    _db.zd_comment_n = 0; // (samp_mdb.FDb.zd_comment)
    _db.zd_comment_tail = NULL; // (samp_mdb.FDb.zd_comment)
    _db.bh_task_max   	= 0; // (samp_mdb.FDb.bh_task)
    _db.bh_task_n     	= 0; // (samp_mdb.FDb.bh_task)
    _db.bh_task_elems 	= NULL; // (samp_mdb.FDb.bh_task)
    _db.zd_task_priority_head = NULL; // (samp_mdb.FDb.zd_task_priority)
    _db.zd_task_priority_n = 0; // (samp_mdb.FDb.zd_task_priority)
    _db.zd_task_priority_tail = NULL; // (samp_mdb.FDb.zd_task_priority)
    // quote: initialize Tpool
    _db.quote_free      = NULL;
    _db.quote_blocksize = algo::BumpToPow2(64 * sizeof(samp_mdb::Quote)); // allocate 64-127 elements at a time
    _db.zd_quote_head = NULL; // (samp_mdb.FDb.zd_quote)
    _db.zd_quote_n = 0; // (samp_mdb.FDb.zd_quote)
    _db.zd_quote_tail = NULL; // (samp_mdb.FDb.zd_quote)

    samp_mdb::InitReflection();
}

