// --- samp_mdb.FieldId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* samp_mdb::value_ToCstr(const samp_mdb::FieldId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case samp_mdb_FieldId_comment      : ret = "comment";  break;
        case samp_mdb_FieldId_p_task       : ret = "p_task";  break;
        case samp_mdb_FieldId_p_user       : ret = "p_user";  break;
        case samp_mdb_FieldId_text         : ret = "text";  break;
        case samp_mdb_FieldId_project      : ret = "project";  break;
        case samp_mdb_FieldId_description  : ret = "description";  break;
        case samp_mdb_FieldId_status       : ret = "status";  break;
        case samp_mdb_FieldId_zd_task      : ret = "zd_task";  break;
        case samp_mdb_FieldId_c_high_priority_task: ret = "c_high_priority_task";  break;
        case samp_mdb_FieldId_quote        : ret = "quote";  break;
        case samp_mdb_FieldId_symbol       : ret = "symbol";  break;
        case samp_mdb_FieldId_price        : ret = "price";  break;
        case samp_mdb_FieldId_ts           : ret = "ts";  break;
        case samp_mdb_FieldId_task         : ret = "task";  break;
        case samp_mdb_FieldId_title        : ret = "title";  break;
        case samp_mdb_FieldId_priority     : ret = "priority";  break;
        case samp_mdb_FieldId_p_project    : ret = "p_project";  break;
        case samp_mdb_FieldId_user         : ret = "user";  break;
        case samp_mdb_FieldId_email        : ret = "email";  break;
        case samp_mdb_FieldId_role         : ret = "role";  break;
        case samp_mdb_FieldId_value        : ret = "value";  break;
    }
    return ret;
}

// --- samp_mdb.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void samp_mdb::value_Print(const samp_mdb::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- samp_mdb.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool samp_mdb::value_SetStrptrMaybe(samp_mdb::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 2: {
            switch (u64(algo::ReadLE16(rhs.elems))) {
                case LE_STR2('t','s'): {
                    value_SetEnum(parent,samp_mdb_FieldId_ts); ret = true; break;
                }
            }
            break;
        }
        case 4: {
            switch (u64(algo::ReadLE32(rhs.elems))) {
                case LE_STR4('r','o','l','e'): {
                    value_SetEnum(parent,samp_mdb_FieldId_role); ret = true; break;
                }
                case LE_STR4('t','a','s','k'): {
                    value_SetEnum(parent,samp_mdb_FieldId_task); ret = true; break;
                }
                case LE_STR4('t','e','x','t'): {
                    value_SetEnum(parent,samp_mdb_FieldId_text); ret = true; break;
                }
                case LE_STR4('u','s','e','r'): {
                    value_SetEnum(parent,samp_mdb_FieldId_user); ret = true; break;
                }
            }
            break;
        }
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('e','m','a','i','l'): {
                    value_SetEnum(parent,samp_mdb_FieldId_email); ret = true; break;
                }
                case LE_STR5('p','r','i','c','e'): {
                    value_SetEnum(parent,samp_mdb_FieldId_price); ret = true; break;
                }
                case LE_STR5('q','u','o','t','e'): {
                    value_SetEnum(parent,samp_mdb_FieldId_quote); ret = true; break;
                }
                case LE_STR5('t','i','t','l','e'): {
                    value_SetEnum(parent,samp_mdb_FieldId_title); ret = true; break;
                }
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,samp_mdb_FieldId_value); ret = true; break;
                }
            }
            break;
        }
        case 6: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(algo::ReadLE16(rhs.elems+4))<<32)) {
                case LE_STR6('p','_','t','a','s','k'): {
                    value_SetEnum(parent,samp_mdb_FieldId_p_task); ret = true; break;
                }
                case LE_STR6('p','_','u','s','e','r'): {
                    value_SetEnum(parent,samp_mdb_FieldId_p_user); ret = true; break;
                }
                case LE_STR6('s','t','a','t','u','s'): {
                    value_SetEnum(parent,samp_mdb_FieldId_status); ret = true; break;
                }
                case LE_STR6('s','y','m','b','o','l'): {
                    value_SetEnum(parent,samp_mdb_FieldId_symbol); ret = true; break;
                }
            }
            break;
        }
        case 7: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(algo::ReadLE16(rhs.elems+4))<<32)|(u64(rhs[6])<<48)) {
                case LE_STR7('c','o','m','m','e','n','t'): {
                    value_SetEnum(parent,samp_mdb_FieldId_comment); ret = true; break;
                }
                case LE_STR7('p','r','o','j','e','c','t'): {
                    value_SetEnum(parent,samp_mdb_FieldId_project); ret = true; break;
                }
                case LE_STR7('z','d','_','t','a','s','k'): {
                    value_SetEnum(parent,samp_mdb_FieldId_zd_task); ret = true; break;
                }
            }
            break;
        }
        case 8: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('p','r','i','o','r','i','t','y'): {
                    value_SetEnum(parent,samp_mdb_FieldId_priority); ret = true; break;
                }
            }
            break;
        }
        case 9: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('p','_','p','r','o','j','e','c'): {
                    if (memcmp(rhs.elems+8,"t",1)==0) { value_SetEnum(parent,samp_mdb_FieldId_p_project); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 11: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('d','e','s','c','r','i','p','t'): {
                    if (memcmp(rhs.elems+8,"ion",3)==0) { value_SetEnum(parent,samp_mdb_FieldId_description); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 20: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('c','_','h','i','g','h','_','p'): {
                    if (memcmp(rhs.elems+8,"riority_task",12)==0) { value_SetEnum(parent,samp_mdb_FieldId_c_high_priority_task); ret = true; break; }
                    break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- samp_mdb.FieldId.value.SetStrptr
