// --- samp_mdb.Project.zd_task.Cascdel
// Delete all elements in the linked list.
void samp_mdb::zd_task_Cascdel(samp_mdb::Project& project) {
    while (samp_mdb::Task *zd_task_first = zd_task_First(project)) {
        task_Delete(*zd_task_first);
    }
}

// --- samp_mdb.Project.zd_task.Insert
// Insert row into linked list. If row is already in linked list, do nothing.
void samp_mdb::zd_task_Insert(samp_mdb::Project& project, samp_mdb::Task& row) {
    if (!project_zd_task_InLlistQ(row)) {
        samp_mdb::Task* old_tail = project.zd_task_tail;
        row.project_zd_task_next = NULL;
        row.project_zd_task_prev = old_tail;
        project.zd_task_tail = &row;
        samp_mdb::Task **new_row_a = &old_tail->project_zd_task_next;
        samp_mdb::Task **new_row_b = &project.zd_task_head;
        samp_mdb::Task **new_row = old_tail ? new_row_a : new_row_b;
        *new_row = &row;
        project.zd_task_n++;
    }
}

// --- samp_mdb.Project.zd_task.Remove
// Remove element from index. If element is not in index, do nothing.
void samp_mdb::zd_task_Remove(samp_mdb::Project& project, samp_mdb::Task& row) {
    if (project_zd_task_InLlistQ(row)) {
        samp_mdb::Task* old_head       = project.zd_task_head;
        (void)old_head; // in case it's not used
        samp_mdb::Task* prev = row.project_zd_task_prev;
        samp_mdb::Task* next = row.project_zd_task_next;
        // if element is first, adjust list head; otherwise, adjust previous element's next
        samp_mdb::Task **new_next_a = &prev->project_zd_task_next;
        samp_mdb::Task **new_next_b = &project.zd_task_head;
        samp_mdb::Task **new_next = prev ? new_next_a : new_next_b;
        *new_next = next;
        // if element is last, adjust list tail; otherwise, adjust next element's prev
        samp_mdb::Task **new_prev_a = &next->project_zd_task_prev;
        samp_mdb::Task **new_prev_b = &project.zd_task_tail;
        samp_mdb::Task **new_prev = next ? new_prev_a : new_prev_b;
        *new_prev = prev;
        project.zd_task_n--;
        row.project_zd_task_next=(samp_mdb::Task*)-1; // not-in-list
    }
}

// --- samp_mdb.Project.zd_task.RemoveAll
// Empty the index. (The rows are not deleted)
void samp_mdb::zd_task_RemoveAll(samp_mdb::Project& project) {
    samp_mdb::Task* row = project.zd_task_head;
    project.zd_task_head = NULL;
    project.zd_task_tail = NULL;
    project.zd_task_n = 0;
    while (row) {
        samp_mdb::Task* row_next = row->project_zd_task_next;
        row->project_zd_task_next  = (samp_mdb::Task*)-1;
        row->project_zd_task_prev  = NULL;
        row = row_next;
    }
}

// --- samp_mdb.Project.zd_task.RemoveFirst
// If linked list is empty, return NULL. Otherwise unlink and return pointer to first element.
samp_mdb::Task* samp_mdb::zd_task_RemoveFirst(samp_mdb::Project& project) {
    samp_mdb::Task *row = NULL;
    row = project.zd_task_head;
    if (row) {
        samp_mdb::Task *next = row->project_zd_task_next;
        project.zd_task_head = next;
        samp_mdb::Task **new_end_a = &next->project_zd_task_prev;
        samp_mdb::Task **new_end_b = &project.zd_task_tail;
        samp_mdb::Task **new_end = next ? new_end_a : new_end_b;
        *new_end = NULL;
        project.zd_task_n--;
        row->project_zd_task_next = (samp_mdb::Task*)-1; // mark as not-in-list
    }
    return row;
}

// --- samp_mdb.Project.c_high_priority_task.Insert
// Insert pointer to row into array. Row must not already be in array.
// If pointer is already in the array, it may be inserted twice.
void samp_mdb::c_high_priority_task_Insert(samp_mdb::Project& project, samp_mdb::Task& row) {
    c_high_priority_task_Reserve(project, 1);
    u32 n  = project.c_high_priority_task_n++;
    project.c_high_priority_task_elems[n] = &row;
}

// --- samp_mdb.Project.c_high_priority_task.ScanInsertMaybe
// Insert pointer to row in array.
// If row is already in the array, do nothing.
// Linear search is used to locate the element.
// Return value: whether element was inserted into array.
bool samp_mdb::c_high_priority_task_ScanInsertMaybe(samp_mdb::Project& project, samp_mdb::Task& row) {
    bool retval = true;
    u32 n  = project.c_high_priority_task_n;
    for (u32 i = 0; i < n; i++) {
        if (project.c_high_priority_task_elems[i] == &row) {
            retval = false;
            break;
        }
    }
    if (retval) {
        // reserve space
        c_high_priority_task_Reserve(project, 1);
        project.c_high_priority_task_elems[n] = &row;
        project.c_high_priority_task_n = n+1;
    }
    return retval;
}

// --- samp_mdb.Project.c_high_priority_task.Remove
// Find element using linear scan. If element is in array, remove, otherwise do nothing
void samp_mdb::c_high_priority_task_Remove(samp_mdb::Project& project, samp_mdb::Task& row) {
    int n = project.c_high_priority_task_n;
    int j=0;
    for (int i=0; i<n; i++) {
        if (project.c_high_priority_task_elems[i] == &row) {
        } else {
            if (j != i) {
                project.c_high_priority_task_elems[j] = project.c_high_priority_task_elems[i];
            }
            j++;
        }
    }
    project.c_high_priority_task_n = j;
}

// --- samp_mdb.Project.c_high_priority_task.Reserve
// Reserve space in index for N more elements;
void samp_mdb::c_high_priority_task_Reserve(samp_mdb::Project& project, u32 n) {
    u32 old_max = project.c_high_priority_task_max;
    if (UNLIKELY(project.c_high_priority_task_n + n > old_max)) {
        u32 new_max  = u32_Max(4, old_max * 2);
        u32 old_size = old_max * sizeof(samp_mdb::Task*);
        u32 new_size = new_max * sizeof(samp_mdb::Task*);
        void *new_mem = algo_lib::malloc_ReallocMem(project.c_high_priority_task_elems, old_size, new_size);
        if (UNLIKELY(!new_mem)) {
            FatalErrorExit("samp_mdb.out_of_memory  field:samp_mdb.Project.c_high_priority_task");
        }
        project.c_high_priority_task_elems = (samp_mdb::Task**)new_mem;
        project.c_high_priority_task_max = new_max;
    }
}

// --- samp_mdb.Project..ReadFieldMaybe
bool samp_mdb::Project_ReadFieldMaybe(samp_mdb::Project& parent, algo::strptr field, algo::strptr strval) {
    bool retval = true;
    samp_mdb::FieldId field_id;
    (void)value_SetStrptrMaybe(field_id,field);
    switch(field_id) {
        case samp_mdb_FieldId_project: {
            retval = algo::Smallstr50_ReadStrptrMaybe(parent.project, strval);
        } break;
        case samp_mdb_FieldId_description: {
            retval = algo::Smallstr200_ReadStrptrMaybe(parent.description, strval);
        } break;
        case samp_mdb_FieldId_status: {
            retval = algo::Smallstr20_ReadStrptrMaybe(parent.status, strval);
        } break;
        case samp_mdb_FieldId_zd_task: {
            retval = false;
        } break;
        case samp_mdb_FieldId_c_high_priority_task: {
            retval = false;
        } break;
        default: {
            retval = false;
            algo_lib::AppendErrtext("comment", "unrecognized attr");
        } break;
    }
    if (!retval) {
        algo_lib::AppendErrtext("attr",field);
    }
    return retval;
}

// --- samp_mdb.Project..ReadStrptrMaybe
// Read fields of samp_mdb::Project from an ascii string.
// The format of the string is an ssim Tuple
bool samp_mdb::Project_ReadStrptrMaybe(samp_mdb::Project &parent, algo::strptr in_str) {
    bool retval = true;
    retval = algo::StripTypeTag(in_str, "samp_mdb.Project");
    ind_beg(algo::Attr_curs, attr, in_str) {
        retval = retval && Project_ReadFieldMaybe(parent, attr.name, attr.value);
    }ind_end;
    return retval;
}

// --- samp_mdb.Project..Uninit
void samp_mdb::Project_Uninit(samp_mdb::Project& project) {
    samp_mdb::Project &row = project; (void)row;
    zd_task_Cascdel(project); // dmmeta.cascdel:samp_mdb.Project.zd_task
    ind_project_Remove(row); // remove project from index ind_project
    zd_project_Remove(row); // remove project from index zd_project

    // samp_mdb.Project.c_high_priority_task.Uninit (Ptrary)  //Array of high priority tasks
    algo_lib::malloc_FreeMem(project.c_high_priority_task_elems, sizeof(samp_mdb::Task*)*project.c_high_priority_task_max); // (samp_mdb.Project.c_high_priority_task)
}

