// --- samp_mdb.User.zd_task.Remove
// Remove element from index. If element is not in index, do nothing.
void samp_mdb::zd_task_Remove(samp_mdb::User& user, samp_mdb::Task& row) {
    if (user_zd_task_InLlistQ(row)) {
        samp_mdb::Task* old_head       = user.zd_task_head;
        (void)old_head; // in case it's not used
        samp_mdb::Task* prev = row.user_zd_task_prev;
        samp_mdb::Task* next = row.user_zd_task_next;
        // if element is first, adjust list head; otherwise, adjust previous element's next
        samp_mdb::Task **new_next_a = &prev->user_zd_task_next;
        samp_mdb::Task **new_next_b = &user.zd_task_head;
        samp_mdb::Task **new_next = prev ? new_next_a : new_next_b;
        *new_next = next;
        // if element is last, adjust list tail; otherwise, adjust next element's prev
        samp_mdb::Task **new_prev_a = &next->user_zd_task_prev;
        samp_mdb::Task **new_prev_b = &user.zd_task_tail;
        samp_mdb::Task **new_prev = next ? new_prev_a : new_prev_b;
        *new_prev = prev;
        user.zd_task_n--;
        row.user_zd_task_next=(samp_mdb::Task*)-1; // not-in-list
    }
}

// --- samp_mdb.User.zd_task.RemoveAll
// Empty the index. (The rows are not deleted)
void samp_mdb::zd_task_RemoveAll(samp_mdb::User& user) {
    samp_mdb::Task* row = user.zd_task_head;
    user.zd_task_head = NULL;
    user.zd_task_tail = NULL;
    user.zd_task_n = 0;
    while (row) {
        samp_mdb::Task* row_next = row->user_zd_task_next;
        row->user_zd_task_next  = (samp_mdb::Task*)-1;
        row->user_zd_task_prev  = NULL;
        row = row_next;
    }
}

// --- samp_mdb.User.zd_task.RemoveFirst
// If linked list is empty, return NULL. Otherwise unlink and return pointer to first element.
samp_mdb::Task* samp_mdb::zd_task_RemoveFirst(samp_mdb::User& user) {
    samp_mdb::Task *row = NULL;
    row = user.zd_task_head;
    if (row) {
        samp_mdb::Task *next = row->user_zd_task_next;
        user.zd_task_head = next;
        samp_mdb::Task **new_end_a = &next->user_zd_task_prev;
        samp_mdb::Task **new_end_b = &user.zd_task_tail;
        samp_mdb::Task **new_end = next ? new_end_a : new_end_b;
        *new_end = NULL;
        user.zd_task_n--;
        row->user_zd_task_next = (samp_mdb::Task*)-1; // mark as not-in-list
    }
    return row;
}

// --- samp_mdb.User..ReadFieldMaybe
bool samp_mdb::User_ReadFieldMaybe(samp_mdb::User& parent, algo::strptr field, algo::strptr strval) {
    bool retval = true;
    samp_mdb::FieldId field_id;
    (void)value_SetStrptrMaybe(field_id,field);
    switch(field_id) {
        case samp_mdb_FieldId_user: {
            retval = algo::Smallstr50_ReadStrptrMaybe(parent.user, strval);
        } break;
        case samp_mdb_FieldId_email: {
            retval = algo::Smallstr100_ReadStrptrMaybe(parent.email, strval);
        } break;
        case samp_mdb_FieldId_role: {
            retval = algo::Smallstr20_ReadStrptrMaybe(parent.role, strval);
        } break;
        case samp_mdb_FieldId_zd_task: {
            retval = false;
        } break;
        default: {
            retval = false;
            algo_lib::AppendErrtext("comment", "unrecognized attr");
        } break;
    }
    if (!retval) {
        algo_lib::AppendErrtext("attr",field);
    }
    return retval;
}

// --- samp_mdb.User..ReadStrptrMaybe
// Read fields of samp_mdb::User from an ascii string.
// The format of the string is an ssim Tuple
bool samp_mdb::User_ReadStrptrMaybe(samp_mdb::User &parent, algo::strptr in_str) {
    bool retval = true;
    retval = algo::StripTypeTag(in_str, "samp_mdb.User");
    ind_beg(algo::Attr_curs, attr, in_str) {
        retval = retval && User_ReadFieldMaybe(parent, attr.name, attr.value);
    }ind_end;
    return retval;
}

// --- samp_mdb.User..Uninit
void samp_mdb::User_Uninit(samp_mdb::User& user) {
    samp_mdb::User &row = user; (void)row;
    zd_task_Cascdel(user); // dmmeta.cascdel:samp_mdb.User.zd_task
    ind_user_Remove(row); // remove user from index ind_user
    zd_user_Remove(row); // remove user from index zd_user
}

// --- samp_mdb.User..Print
// print string representation of ROW to string STR
// cfmt:samp_mdb.User.String  printfmt:Tuple
void samp_mdb::User_Print(samp_mdb::User& row, algo::cstring& str) {
    algo::tempstr temp;
    str << "samp_mdb.User";

    algo::Smallstr50_Print(row.user, temp);
    PrintAttrSpaceReset(str,"user", temp);

    algo::Smallstr100_Print(row.email, temp);
    PrintAttrSpaceReset(str,"email", temp);

    algo::Smallstr20_Print(row.role, temp);
    PrintAttrSpaceReset(str,"role", temp);
}

